func NewAssociationListValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (AssociationListValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing AssociationListValue Attribute Value",
				"While creating a AssociationListValue value, a missing attribute value was detected. "+
					"A AssociationListValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("AssociationListValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid AssociationListValue Attribute Type",
				"While creating a AssociationListValue value, an invalid attribute value was detected. "+
					"A AssociationListValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("AssociationListValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("AssociationListValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra AssociationListValue Attribute Value",
				"While creating a AssociationListValue value, an extra attribute value was detected. "+
					"A AssociationListValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra AssociationListValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewAssociationListValueUnknown(), diags
	}

	pVlanAttribute, ok := attributes["p_vlan"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`p_vlan is missing from object`)

		return NewAssociationListValueUnknown(), diags
	}

	pVlanVal, ok := pVlanAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`p_vlan expected to be basetypes.Int64Value, was: %T`, pVlanAttribute))
	}

	sVlanAttribute, ok := attributes["s_vlan"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`s_vlan is missing from object`)

		return NewAssociationListValueUnknown(), diags
	}

	sVlanVal, ok := sVlanAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`s_vlan expected to be basetypes.Int64Value, was: %T`, sVlanAttribute))
	}

	if diags.HasError() {
		return NewAssociationListValueUnknown(), diags
	}

	return AssociationListValue{
		PVlan: pVlanVal,
		SVlan: sVlanVal,
		state: attr.ValueStateKnown,
	}, diags
}

func NewAssociationListValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) AssociationListValue {
	object, diags := NewAssociationListValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewAssociationListValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t AssociationListType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewAssociationListValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewAssociationListValueUnknown(), nil
	}

	if in.IsNull() {
		return NewAssociationListValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewAssociationListValueMust(AssociationListValue{}.AttributeTypes(ctx), attributes), nil
}

